        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "그의 느리고 부지런함, 그의 유순함. 그러면서도 일생에 한두 번 노할 때에는 그 우렁찬 영각, 횃불 같은 눈으로 뿔이 꺾이도록 맥진(驀進)함, 그의 침묵함...", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "아이들에게도 순순히 끌려가는 모습이 예수와 닮아 거룩해 보이기도 하다.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "조선인은 허위(虛僞)되고, 공상과 공론만 즐겨 나태하고, 서로 신의와 충성심이 없고 술수를 부리며, 임사(매사)에 용기가 없고, 이기적이어서 사회봉사심과 단결력이 없고, 극히 빈궁하고.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "일반 민중이 도덕적 이상이 퇴폐해서 인생의 의무라든가 사업이라든가 하는 높은 희구를 버리고 오직 성욕과 호기심만 따르게 되니, 에로란 성욕적 흥미를 만족시키는 관념군이요 그로란 호기벽을 만족시킬 만한 관념군.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "주정 잘하기로 첫째가 아라사(俄羅斯), 둘째가 일본, 셋째가 조선사람", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "우리 조선 민족이 혈통적으로, 문화적으로 대단히 단일한 민족이라는 것은 우리 조선인 된 이는 누구나 분명히 의식하여 일점의 의심도 없는 바다.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "식민지하에서의 모든 활동은 비정치적이어야 한다.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "일종의 극적 광경이라고나 할까. 황국을 위해 전장에 나가 죽자는 생각이 모두의 얼굴에 드러났더군요.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "조국을 위해 친일했다.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "보통 사람이란 자신보다 만만한 자에게는 한없이 잔인하고 비열해지는 인간이 보통 사람이다.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "사찰의 개왓장마다 찬 땀이 흐를 일", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "국가의 생명과 나의 생명과는 그 운명을 같이하는 줄을 깨달았노라… 나는 이름만일 망정 극단의 크리스천으로, 대동주의자로, 허무주의자로, 본능만족주의자로 드디어 애국주의에 정박하였노라.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "정직하지 못한 사람들이 만든 사회가 올바르게 운영될수 있을까?", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "얼마 후에 결국 한국의 토지는 뜨거운 모래가 막막한 사막이 되어 푸른 언덕은 공허한 역사적 이름이 되어 후대의 사람들의 호기심만을 움직일 뿐이게 될 것이나이다. 조선 민족의 생사는 한산의 초목과 그 생사흥망을 같이해야 함에 있을진저.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "저 ‘화랑’의 사상이란 오늘날 막 바로 부활시켜도 좋다고 생각합니다.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "세말이 되면 진고개와 종로에서 장, 단스 같은 것을 일등상으로 걸어놓고 경품부 대매출을 한다. 그때마다 안해는 장이 빠지기를 바라고 물건을 삿다. 그러나 뽑는 것마다 타울수건, 화저까락 따위요, 바라는 장은 아니 빠졌다.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "멀리서 희미하게 안개 낀 한산(韓山)이 눈에 들어왔을 때의 나의 심정은 어떠한 것이었을까. 무언가, 한산에는 태양의 빛도, 우주에 가득 차 흐르는 태양의 광선도 여기 한산에는 비추지 않는 모양이다.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "히로시마의 활짝 갠 하늘과 뜨거운 태양이 일본 풍경의 주된 색조를 이루고 있다면 조국 조선은 \"태양의 빛도, 우주에 가득 차 흐르는 태양의 광선도 비추지 않는\" 검은색의 풍경이다.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "일어나라, 우리 소년 제군!", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "소년제군이여, 이것을 듣고 어떠한 느낌을 일어나느뇨. 천제(天帝)께서 인생(人生)을 만들 때에 동등하게 두 눈, 두 손, 두 다리를 내려 주신 것이 아닌가. 어떠한 부족함이 있어서 저들 왜국(倭國)에 의해 압제(壓制)를 받는 것인가. 이목구비를 갖춘 신한소년 제군은 이것을 생각하여 세월을 헛되이 하지 말고 자기의 목적과 자기의 천재를 발휘하여 그 목적지를 향해 서둘러라, 신한(新韓)을 어깨에 짊어질 대한 소년들이여", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "체격이 팔다리나 몸통이 자로 잰 듯 너무 길지도 짧지도 않게 바로 맞고, 몸 쓰는 것, 걷는 것 등 모든 동작이 날씬하여 남의 눈에 조금도 거슬리게 보이지 않고... 또 취미와 그 정신이 아울러 고상하다면 그야말로 내가 찾는 미인이 될 것", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "얼굴은 둥글둥글한 타원형의 윤곽에다가 눈은 어디까지든지 크고 처진 듯하며 코나 귀가 복스럽게 예쁘고 살결이 하얀 분", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "아랫목에 '뜻뜻이' 등을 굽고 있는 생활은 암만 해도 투쟁보다도 은둔을 의미한다.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "우리 민족이 살 수 있는 길은 '독립을 포기하는 것'이며 모두 일본국민이 될 것", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "일제의 한반도 지배가 36년 만에 끝나지 않고 100년 이상 계속될 줄 알았다.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "설산은 호 그대로 개방적이요, 결백하고 어린애와 같이 표리가 없는 사람", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "창파에는 명월이요, 청산에는 청풍이라.", Author = "이광수" },
            new Quote { Id = "https://ko.wikiquote.org/wiki/이광수", Text = "나에게 아무 것도 베푼 게 없는 조국을 위해 최선을 다해 살았건만 돌아온 것은 민족의 변절자라는 비난뿐", Author = "이광수" },
        };
